-- 一次性迁移模板：先运行对应 inventory，备份并审阅表名、映射及冲突。
-- 默认最终 ROLLBACK；正式执行须明确改为 COMMIT。不要使用客户端忽略错误选项。
-- 仅 language_lines.text 的语言键；不改 group/key，不作为运行时兼容层。
BEGIN IMMEDIATE;
CREATE TEMPORARY TABLE openrust_locale_guard (valid INTEGER NOT NULL CHECK (valid = 1));
-- 冲突或未知旧键会触发约束失败，必须回滚整个事务，禁止覆盖两份内容。
INSERT INTO openrust_locale_guard SELECT CASE WHEN EXISTS (SELECT 1 FROM language_lines WHERE ((json_type("text", '$."zh_CN"') IS NOT NULL AND json_type("text", '$."zh-Hans"') IS NOT NULL) OR (json_type("text", '$."zh_TW"') IS NOT NULL AND json_type("text", '$."zh-Hant"') IS NOT NULL) OR (json_type("text", '$."en_US"') IS NOT NULL AND json_type("text", '$."en-US"') IS NOT NULL) OR (json_type("text", '$."en_GB"') IS NOT NULL AND json_type("text", '$."en-GB"') IS NOT NULL)) OR (EXISTS (SELECT 1 FROM json_each("text") AS tags WHERE instr(tags.key, '_') > 0 AND tags.key NOT IN ('zh_CN', 'zh_TW', 'en_US', 'en_GB')))) THEN 0 ELSE 1 END;
UPDATE language_lines SET "text" = CASE WHEN json_type("text", '$."en_GB"') IS NOT NULL THEN json_remove(json_set(CASE WHEN json_type("text", '$."en_US"') IS NOT NULL THEN json_remove(json_set(CASE WHEN json_type("text", '$."zh_TW"') IS NOT NULL THEN json_remove(json_set(CASE WHEN json_type("text", '$."zh_CN"') IS NOT NULL THEN json_remove(json_set("text", '$."zh-Hans"', "text" -> '$."zh_CN"'), '$."zh_CN"') ELSE "text" END, '$."zh-Hant"', "text" -> '$."zh_TW"'), '$."zh_TW"') ELSE CASE WHEN json_type("text", '$."zh_CN"') IS NOT NULL THEN json_remove(json_set("text", '$."zh-Hans"', "text" -> '$."zh_CN"'), '$."zh_CN"') ELSE "text" END END, '$."en-US"', "text" -> '$."en_US"'), '$."en_US"') ELSE CASE WHEN json_type("text", '$."zh_TW"') IS NOT NULL THEN json_remove(json_set(CASE WHEN json_type("text", '$."zh_CN"') IS NOT NULL THEN json_remove(json_set("text", '$."zh-Hans"', "text" -> '$."zh_CN"'), '$."zh_CN"') ELSE "text" END, '$."zh-Hant"', "text" -> '$."zh_TW"'), '$."zh_TW"') ELSE CASE WHEN json_type("text", '$."zh_CN"') IS NOT NULL THEN json_remove(json_set("text", '$."zh-Hans"', "text" -> '$."zh_CN"'), '$."zh_CN"') ELSE "text" END END END, '$."en-GB"', "text" -> '$."en_GB"'), '$."en_GB"') ELSE CASE WHEN json_type("text", '$."en_US"') IS NOT NULL THEN json_remove(json_set(CASE WHEN json_type("text", '$."zh_TW"') IS NOT NULL THEN json_remove(json_set(CASE WHEN json_type("text", '$."zh_CN"') IS NOT NULL THEN json_remove(json_set("text", '$."zh-Hans"', "text" -> '$."zh_CN"'), '$."zh_CN"') ELSE "text" END, '$."zh-Hant"', "text" -> '$."zh_TW"'), '$."zh_TW"') ELSE CASE WHEN json_type("text", '$."zh_CN"') IS NOT NULL THEN json_remove(json_set("text", '$."zh-Hans"', "text" -> '$."zh_CN"'), '$."zh_CN"') ELSE "text" END END, '$."en-US"', "text" -> '$."en_US"'), '$."en_US"') ELSE CASE WHEN json_type("text", '$."zh_TW"') IS NOT NULL THEN json_remove(json_set(CASE WHEN json_type("text", '$."zh_CN"') IS NOT NULL THEN json_remove(json_set("text", '$."zh-Hans"', "text" -> '$."zh_CN"'), '$."zh_CN"') ELSE "text" END, '$."zh-Hant"', "text" -> '$."zh_TW"'), '$."zh_TW"') ELSE CASE WHEN json_type("text", '$."zh_CN"') IS NOT NULL THEN json_remove(json_set("text", '$."zh-Hans"', "text" -> '$."zh_CN"'), '$."zh_CN"') ELSE "text" END END END END
WHERE json_type("text", '$."zh_CN"') IS NOT NULL OR json_type("text", '$."zh_TW"') IS NOT NULL OR json_type("text", '$."en_US"') IS NOT NULL OR json_type("text", '$."en_GB"') IS NOT NULL;
DROP TABLE openrust_locale_guard;
ROLLBACK;
